def _disk_format(command: SimpleCommand, ctx: RuleContext) -> str | None:
    if _FORMATTERS.match(command.name) and _names_device(command):
        return command.name
    if command.name == "parted":
        return _parted(command)
    if command.name in ("fdisk", "gdisk", "sgdisk") and not short_flag(command.args, "l"):
        return command.name
    if command.name == "diskutil" and command.args and command.args[0] in _DISKUTIL_DESTRUCTIVE:
        # `diskutil apfs list` is harmless; `diskutil apfs deleteContainer` is not.
        apfs_destructive = command.args[1:2] and command.args[1].startswith(("delete", "erase"))
        if command.args[0] != "apfs" or apfs_destructive:
            return f"diskutil {command.args[0]}"
    return None


# --------------------------------------------------------------------------- #
# Fetch-and-execute and decode-and-execute
# --------------------------------------------------------------------------- #

_FETCHERS = frozenset({"curl", "wget", "fetch", "aria2c", "http", "https", "xh", "xhs", "httpie",
                       "nc", "ncat", "netcat", "socat", "lwp-request", "GET"})
_DECODERS = frozenset({"base64", "base32", "xxd", "openssl", "uudecode", "gunzip", "zcat", "rev"})
_FETCH_IN_ARG = re.compile(r"(?:\$\(|<\(|`)\s*(?:\S*/)?(?:curl|wget|fetch|aria2c|http|https|xh)\b")


def _executes_stdin(command: SimpleCommand) -> bool:
    """A shell or interpreter that will run whatever arrives on stdin."""
    name, args = command.name, command.args
    if name in SHELLS:
        shell = shell_invocation(name, args)
        return shell.reads_stdin and not shell.syntax_only
    if interpreter_kind(name) == "python":
        module, module_args, flags = _python_options(args)
        if _inspects(command, flags):
            return True
        if module is not None:
            # `python3 -m json.tool` reads stdin as data; `python3 -m code` runs it.
            rest = operands(module_args)
            return module not in _STDIN_DATA_MODULES and (not rest or rest[0] in STDIN_PATHS)
    if interpreter_kind(name):
        script_args = operands(args, frozenset({"-W", "-X", "-m", "-r", "-I", "-M"}))
        return not script_args or script_args[0] in STDIN_PATHS
    return name in ("eval", "source", ".")


# Modules that read stdin as data. Any other module may run it (`python3 -m code`).
_STDIN_DATA_MODULES = frozenset({"json", "json.tool", "base64"})


def _inspects(command: SimpleCommand, flags: str) -> bool:
    """`python3 -i` (or PYTHONINSPECT) reads stdin as code once the script or module is done."""
    inspect = dict(command.environment).get("PYTHONINSPECT", ())
    return "i" in flags or any(inspect)


def _python_options(args: tuple[str, ...]) -> tuple[str | None, tuple[str, ...], str]:
    """Python's options, read the way Python reads them: the module of
    `python3 -m NAME ARGS...` (also `-mNAME`, `-Im NAME`) or None, the module's
    arguments, and the short flags given before it. `-c`, `-W` and `-X` take a
    value, so `-Wm` has no module."""
    index, flags = 0, ""
    while index < len(args):
        arg = args[index]
        index += 1
        if arg in ("-", "--") or not arg.startswith("-"):
            break
        if arg.startswith("--"):
            continue
        for offset, letter in enumerate(arg[1:], start=2):
            if letter == "c":
                return None, (), flags
            if letter == "m":
                if arg[offset:]:
                    return arg[offset:], args[index:], flags
                return (args[index], args[index + 1:], flags) if index < len(args) else (None, (), flags)
            if letter in "WX":
                index += not arg[offset:]
                break
            flags += letter
    return None, (), flags


def _pipeline_sources(command: SimpleCommand, ctx: RuleContext) -> list[SimpleCommand]:
    found: list[SimpleCommand] = []
    current = ctx.parsed.previous_stage(command)
    while current is not None:
        found.append(current)
        current = ctx.parsed.previous_stage(current)

    # Directory the command runs in, following `cd`/`pushd` earlier in the same
    # line. None when a `cd` target is computed at run time (`cd "$DIR"`).
    cwd: str | None = None
    # Every directory it might run in. A `cd` can fail (missing directory) and
    # `cd a || cd b` runs only one of them, so earlier directories stay possible.
    cwd_options: tuple[str | None, ...] = ()
    # Values each variable may hold when the command starts: its prefix
    # assignments (`X=1 cmd`) and assignments earlier in the line. Programs that
    # read a variable by name (`git --config-env=key=VAR`) look it up here.
    environment: tuple[tuple[str, tuple[str, ...]], ...] = ()

    @property
    def possible_cwds(self) -> tuple[str | None, ...]:
        return self.cwd_options or (self.cwd,)

    @property
    def name(self) -> str:
        return program_name(self.argv[0]) if self.argv else ""

    @property
    def args(self) -> tuple[str, ...]:
        return self.argv[1:]

    def rendered(self) -> str:
        return " ".join(self.argv)

    def origin(self) -> str:
        return " → ".join(self.via)

    def option_on(self, name: str) -> bool:
        """Whether shell option `name` (`shopt -s name`) may be on for this command."""
        return "on" in self.env_values(SHELL_OPTION + name)

    def env_values(self, name: str) -> tuple[str, ...]:
        """Every value `name` may hold in this command's environment; () if unknown."""
        values = next((values for key, values in self.environment if key == name), ())
        return tuple(value for value in values if value != UNSET)


@dataclass(frozen=True)
